<?php
 require_once(__DIR__.'/../init.php'); $serviceClass = 'common_main'; class common_main { const ERROR_INVALID_USER = -1; protected $db; public function readTasks ($params = null) { $cfg = getSessionValue('appConfig'); unsetAppConfigBackend($cfg); return [$cfg]; } public function changeApp () { return new stdClass(); } public function readNavigatorItems ($params) { return $this->loadJsonNavigatorItems([]); } protected function loadJsonNavigatorItems ($roles) { $app = getSessionValue('appConfig')['mainService']; $json = json_decode(file_get_contents(__DIR__.'/../'.$app.'/common/navigatorItems.json'), JSON_OBJECT_AS_ARRAY); $a = ['children' => $this->filterNavigatorItems($json['children'], $roles)]; return $a; } protected function filterNavigatorItems ($items, $userRoles) { foreach ($items as $i => &$value) { if ( isset($value['roles']) ) { $itemRoles = safe_explode(',', $value['roles']); if( !array_intersect($itemRoles, $userRoles) ) { unset($items[$i]); continue; } } if ( isset($value['children']) ) { $value['children'] = $this->filterNavigatorItems($value['children'], $userRoles); } } return array_values($items); } public function vacuumSessions($params) { return vacuumSessions($params); } public function getAccessTimeSessions ($params) { return getAccessTimeSessions($params); } } loadMainService(); handleJsonRpc($serviceClass);